#include "TagTreeMatchObject.h"
#include "TagTreeNodeObject.h"

#include "graphqlservice/internal/Schema.h"

#include "graphqlservice/introspection/IntrospectionSchema.h"

#include <algorithm>
#include <functional>
#include <sstream>
#include <stdexcept>
#include <unordered_map>

using namespace std::literals;

namespace graphql::tagimg {
namespace object {

TagTreeMatch::TagTreeMatch(std::unique_ptr<const Concept> pimpl) noexcept
	: service::Object{ getTypeNames(), getResolvers() }
	, _pimpl { std::move(pimpl) }
{
}

service::TypeNames TagTreeMatch::getTypeNames() const noexcept
{
	return {
		R"gql(TagTreeMatch)gql"sv
	};
}

service::ResolverMap TagTreeMatch::getResolvers() const noexcept
{
	return {
		{ R"gql(node)gql"sv, [this](service::ResolverParams&& params) { return resolveNode(std::move(params)); } },
		{ R"gql(ancestors)gql"sv, [this](service::ResolverParams&& params) { return resolveAncestors(std::move(params)); } },
		{ R"gql(__typename)gql"sv, [this](service::ResolverParams&& params) { return resolve_typename(std::move(params)); } },
		{ R"gql(matchedName)gql"sv, [this](service::ResolverParams&& params) { return resolveMatchedName(std::move(params)); } },
		{ R"gql(matchedAlias)gql"sv, [this](service::ResolverParams&& params) { return resolveMatchedAlias(std::move(params)); } }
	};
}

void TagTreeMatch::beginSelectionSet(const service::SelectionSetParams& params) const
{
	_pimpl->beginSelectionSet(params);
}

void TagTreeMatch::endSelectionSet(const service::SelectionSetParams& params) const
{
	_pimpl->endSelectionSet(params);
}

service::AwaitableResolver TagTreeMatch::resolveNode(service::ResolverParams&& params) const
{
	std::unique_lock resolverLock(_resolverMutex);
	service::SelectionSetParams selectionSetParams { static_cast<const service::SelectionSetParams&>(params) };
	auto directives = std::move(params.fieldDirectives);
	auto result = _pimpl->getNode(service::FieldParams { std::move(selectionSetParams), std::move(directives) });
	resolverLock.unlock();

	return service::ModifiedResult<TagTreeNode>::convert(std::move(result), std::move(params));
}

service::AwaitableResolver TagTreeMatch::resolveAncestors(service::ResolverParams&& params) const
{
	std::unique_lock resolverLock(_resolverMutex);
	service::SelectionSetParams selectionSetParams { static_cast<const service::SelectionSetParams&>(params) };
	auto directives = std::move(params.fieldDirectives);
	auto result = _pimpl->getAncestors(service::FieldParams { std::move(selectionSetParams), std::move(directives) });
	resolverLock.unlock();

	return service::ModifiedResult<TagTreeNode>::convert<service::TypeModifier::List>(std::move(result), std::move(params));
}

service::AwaitableResolver TagTreeMatch::resolveMatchedName(service::ResolverParams&& params) const
{
	std::unique_lock resolverLock(_resolverMutex);
	service::SelectionSetParams selectionSetParams { static_cast<const service::SelectionSetParams&>(params) };
	auto directives = std::move(params.fieldDirectives);
	auto result = _pimpl->getMatchedName(service::FieldParams { std::move(selectionSetParams), std::move(directives) });
	resolverLock.unlock();

	return service::ModifiedResult<std::string>::convert(std::move(result), std::move(params));
}

service::AwaitableResolver TagTreeMatch::resolveMatchedAlias(service::ResolverParams&& params) const
{
	std::unique_lock resolverLock(_resolverMutex);
	service::SelectionSetParams selectionSetParams { static_cast<const service::SelectionSetParams&>(params) };
	auto directives = std::move(params.fieldDirectives);
	auto result = _pimpl->getMatchedAlias(service::FieldParams { std::move(selectionSetParams), std::move(directives) });
	resolverLock.unlock();

	return service::ModifiedResult<bool>::convert(std::move(result), std::move(params));
}

service::AwaitableResolver TagTreeMatch::resolve_typename(service::ResolverParams&& params) const
{
	return service::Result<std::string>::convert(std::string{ R"gql(TagTreeMatch)gql" }, std::move(params));
}

} // namespace object

void AddTagTreeMatchDetails(const std::shared_ptr<schema::ObjectType>& typeTagTreeMatch, const std::shared_ptr<schema::Schema>& schema)
{
	typeTagTreeMatch->AddFields({
		schema::Field::Make(R"gql(node)gql"sv, R"md(命中的标签节点。)md"sv, std::nullopt, schema->WrapType(introspection::TypeKind::NON_NULL, schema->LookupType(R"gql(TagTreeNode)gql"sv))),
		schema::Field::Make(R"gql(ancestors)gql"sv, R"md(从根到父级的祖先链，按根到父级排序；命中顶层标签时为空。)md"sv, std::nullopt, schema->WrapType(introspection::TypeKind::NON_NULL, schema->WrapType(introspection::TypeKind::LIST, schema->WrapType(introspection::TypeKind::NON_NULL, schema->LookupType(R"gql(TagTreeNode)gql"sv))))),
		schema::Field::Make(R"gql(matchedName)gql"sv, R"md(命中的标准名或别名。)md"sv, std::nullopt, schema->WrapType(introspection::TypeKind::NON_NULL, schema->LookupType(R"gql(String)gql"sv))),
		schema::Field::Make(R"gql(matchedAlias)gql"sv, R"md(命中的名称是否为别名。)md"sv, std::nullopt, schema->WrapType(introspection::TypeKind::NON_NULL, schema->LookupType(R"gql(Boolean)gql"sv)))
	});
}

} // namespace graphql::tagimg
